SELECT
    COALESCE(SUM(CASE WHEN d.status = 'SUCCEEDED' THEN 1 ELSE 0 END), 0) AS succeeded,
    COALESCE(SUM(CASE WHEN d.status IN ('SUCCEEDED','FAILED','TIMEOUT') THEN 1 ELSE 0 END), 0) AS total,
    COALESCE(SUM(CASE WHEN d.status IN ('FAILED','TIMEOUT') THEN 1 ELSE 0 END), 0) AS failedOrTimeout
FROM dispatch d
WHERE d.tenant_id = #{tenantId}
  AND d.is_deleted = 0

  AND d.gmt_create >= #{start}
  AND d.gmt_create < #{end}

SELECT
    COUNT(DISTINCT d.workitem_id) AS executedWorkitems,
    COUNT(DISTINCT CASE WHEN  THEN d.workitem_id END) AS reworkedWorkitems,
    COALESCE(SUM(CASE WHEN  THEN 1 ELSE 0 END), 0) AS retryCount
FROM dispatch d
WHERE d.tenant_id = #{tenantId}
  AND d.is_deleted = 0

  AND d.gmt_create >= #{start}
  AND d.gmt_create < #{end}

SELECT ROUND(AVG(TIMESTAMPDIFF(MINUTE, successful_workitem.gmt_create, successful_workitem.success_at)))
FROM (

) successful_workitem
WHERE successful_workitem.success_at >= #{start}
  AND successful_workitem.success_at < #{end}
